  /* ── Industries page ────────────────────────────────────────── */
  indp_hero_eyebrow:  'Industries \u00B7 Operator environments where the model fits',
  indp_hero_title:    'Where VitaCoreX earns attention \u2014 and where it doesn\u2019t pretend to fit.',
  indp_hero_lead:     'Four operator environments where the recovery model has a natural home: healthcare & dental (patient-balance aging past 90, portal fragmentation, pre-agency leakage), fleet & logistics (fuel-card swipes without driver attestation, BOLs filed apart from the invoice, unresolved detention), contract-heavy services (change orders without signatures, lien calendars that already slipped, chronology binders missing), and subscription / recurring (retry logic, dunning ladders, and card-on-file flows that were never tuned). If your category isn\u2019t here, the honest answer is probably a different partner.',
  indp_cfp_h:         'Company-first positioning',
  indp_cfp_p:         'These pages support the corporate lane first: recovery design, documentation control, and cleaner handoff before outside cost expands.',
  indp_fit_eyebrow:   'Industry fit',
  indp_fit_title:     'Industry-focused pages so operators recognize their workflow \u2014 and its failure points \u2014 faster.',
  indp_fit_intro:     'Generic positioning can still exist, but narrower entry points help operators see themselves and the specific risks their category carries \u2014 without translating a generic pitch into their own terms.',
  indp_c1_p:          'Healthcare & dental',
  indp_c1_h:          'Patient-balance environments with documentation drag and pre-agency leakage.',
  indp_c1_t:          'Useful where revenue recovery and packet discipline are both breaking down.',
  indp_c2_p:          'Subscription & recurring payments',
  indp_c2_h:          'Recurring billing operators balancing retention sensitivity with recovery discipline.',
  indp_c2_t:          'Useful where dunning, commitments, and exceptions need stronger logic.',
  indp_c3_p:          'Fleet & logistics',
  indp_c3_h:          'Contract-heavy portfolios with dispersed operations and uneven document control.',
  indp_c3_t:          'Useful where supporting records and receivable actions are inconsistent across locations.',
  indp_c4_p:          'Contract-heavy services',
  indp_c4_h:          'Commercial service businesses with invoice, authorization, and escalation complexity.',
  indp_c4_t:          'Useful where weak files and weak handoff logic create avoidable cash drag and cleanup cost.',
  indp_why_p:         'Why this matters',
  indp_why_t:         'Each industry page names the AR and documentation failures that show up most often in that sector \u2014 so you don\u2019t have to translate a generic pitch into your own operation.',
  indp_guard_p:       'Guardrail',
  indp_guard_t:       'We do not promise guaranteed outcomes or fixed dollar recovery. What a fit page explains is who the model suits, how a pilot runs, and which evidence standards apply.',

  /* ── About page ─────────────────────────────────────────────── */
  abt_hero_eyebrow:   'About VitaCoreX',
  abt_hero_title:     'Operational advisory for recovery, documentation control, and cleaner counsel handoff.',
  abt_hero_lead:      'VitaCoreX is positioned for operators that need stronger cash-control logic, cleaner packet discipline, and a more credible handoff before outside cost expands.',
  abt_cfp_h:          'Company-first positioning',
  abt_cfp_p:          'These pages support the corporate lane first: recovery design, documentation control, and cleaner handoff before outside cost expands.',
  abt_c1_p:           'What VitaCoreX does',
  abt_c1_h:           'Builds operational control before expensive escalation.',
  abt_c1_t:           'VitaCoreX helps complex operators improve cash control, documentation discipline, and counsel-ready file structure before avoidable fee pressure expands.',
  abt_c2_p:           'What VitaCoreX does not do',
  abt_c2_h:           'Not legal representation and not licensed collections activity.',
  abt_c2_t:           'The firm does not provide legal advice or act as a law firm. It also does not position itself as a licensed collection agency. Those boundaries stay visible across the site.',
  abt_c3_p:           'What a first engagement produces',
  abt_c3_h:           'Diagnostic clarity, packet standards, and pilot logic.',
  abt_c3_t:           'A serious first phase should produce a work product: a gap map, a recommended workstream, and a measurement path that leadership can actually review.',
  abt_method_eyebrow: 'Method',
  abt_method_title:   'Diagnose, pilot, then scale only when the evidence justifies it.',
  abt_method_intro:   'That is a stronger premium signal than generic promises. It shows operational discipline and keeps the story grounded in what can be documented.',
  abt_ts1_h:          'Diagnose',
  abt_ts1_p:          'Review workflow friction, document quality, escalation logic, and where recoverable value leaks first.',
  abt_ts2_h:          'Pilot',
  abt_ts2_p:          'Define a contained workstream with clear expectations, response windows, and measurement logic.',
  abt_ts3_h:          'Scale',
  abt_ts3_p:          'Expand only when the pilot creates credible operator-owned evidence.',
  abt_fpo_h:          'Typical first-phase outputs',
  abt_fpo_l1:         'Current-state leakage and handoff review',
  abt_fpo_l2:         'Document gap list and packet standard',
  abt_fpo_l3:         'Priority routing logic and next-step memo',
  abt_fpo_l4:         'Pilot scope with measurement criteria',
  abt_lead_eyebrow:   'Leadership',
  abt_lead_title:     'Who runs VitaCoreX.',
  abt_lead_intro:     'Boutique advisory firms are bought as much for the principal as for the method. This page exists to make that principal visible \u2014 and verifiable \u2014 before the first call.',
  abt_founder_role:   'Founder & Managing Director',
  abt_founder_bio1:   'Steven founded VitaCoreX LLC in 2025 to close a practical gap operators kept describing: administrative work that was not legal enough to require outside counsel, but not simple enough to run cleanly in-house \u2014 and that steadily bled margin before anyone escalated it. The firm focuses on three operational lanes: revenue recovery design, corporate legal file control, and structured case intake.',
  abt_founder_bio2:   'VitaCoreX is intentionally positioned as a boutique, non-agency, non-law-firm advisory so engagements stay measurable and handoffs stay clean. Steven works directly with finance-led and counsel-adjacent operators who want cash-control logic and packet discipline in place before outside cost expands. Verification points \u2014 Sunbiz entity record, EIN, and LinkedIn \u2014 are made available before any engagement commitment.',
