  /* ── Case study: Subscription SaaS ──────────────────────────── */
  cssa_hero_eyebrow:  'Case study \u00b7 Composite engagement',
  cssa_hero_title:    'Mid-market SaaS rescues 67% of failed subscription payments in 60 days.',
  cssa_hero_lede:     'A mid-market B2B SaaS platform walked in with $780K in failed renewals and card declines, a standard dunning sequence that had written off too much too early, and retention taking collateral damage. Structured retry design, documentation discipline, and a non-collection outreach tone recovered the window. Here is the engagement in CFO-readable detail.',
  cssa_exec_eyebrow:  'Executive summary',
  cssa_exec_title:    'Three numbers, 60 days.',
  cssa_exec_intro:    'Measured against the operator\u2019s own prior-window dunning performance, reconciled with their billing system at engagement close.',
  cssa_exec_h3:       'Executive summary',
  cssa_exec_1:        '$780K backlog of failed payments cleared across the 60-day window',
  cssa_exec_2:        '67% failed-payment recovery rate (vs 20% with the prior dunning sequence)',
  cssa_exec_3:        '89% customer LTV preserved on recovered accounts \u2014 retention not sacrificed for cash',
  cssa_sit_eyebrow:   'The situation',
  cssa_sit_title:     'Where the book was on day one.',
  cssa_sit_p1:        'A mid-market B2B SaaS platform with a steady renewal engine, priced in the $500\u2013$3K MRR band. The billing system ran a standard dunning sequence \u2014 retry on decline, email on day 3, email on day 7, write-off on day 30. It worked for the happy path. It was generating collateral damage on everything else.',
  cssa_sit_p2:        'The symptoms the CFO came in with:',
  cssa_sit_1:         '$780K in failed renewals and card declines on the 60-day ledger',
  cssa_sit_2:         'Standard dunning had written off accounts the CS team considered recoverable',
  cssa_sit_3:         'Retention taking collateral damage \u2014 customers hit with collection-tone email felt treated as defaults',
  cssa_sit_4:         'No retry intelligence \u2014 every card retry fired on the same cadence regardless of BIN or time-of-month signal',
  cssa_sit_5:         'Exception handling undocumented \u2014 CS team making save-offer decisions case by case, no template',
  cssa_app_eyebrow:   'The approach',
  cssa_app_title:     'Retry intelligence plus professional outreach.',
  cssa_app_p1:        'The intervention was a retry and outreach redesign \u2014 not a collection push. The principle: most failed payments on a mid-market SaaS book are liquidity or card-issue timing, not unwillingness. Treat them as timing failures, not defaults.',
  cssa_app_1:         'Intelligent retry sequencing: card retries scheduled by BIN range and time-of-month signal, not fixed cadence',
  cssa_app_2:         'Professional outreach templates, written in a retention tone \u2014 not collection tone',
  cssa_app_3:         'Structured save-offer playbook: documented discount tiers, pause options, and plan-switch paths',
  cssa_app_4:         'Exception-handling workflow for CS team: written rules for when to escalate, pause, or close',
  cssa_app_5:         'KPI dashboard covering recovery rate, time-to-recovery, LTV preserved, and exception volume',
  cssa_out_eyebrow:   'Outcomes',
  cssa_out_title:     'What the book looked like at day 60.',
  cssa_out_intro:     'All figures measured against the operator\u2019s prior-window dunning baseline and reconciled with their billing system.',
  cssa_out_th1:       'Metric',
  cssa_out_th2:       'Result',
  cssa_out_m1:        'Failed-payment recovery rate',
  cssa_out_v1:        '67% (vs 20% prior)',
  cssa_out_m2:        'Customer LTV preserved',
  cssa_out_v2:        '89% of recovered accounts',
  cssa_out_m3:        'Pilot ROI against fees',
  cssa_out_v3:        '4.1\u00d7 in 60 days',
  cssa_out_m4:        'Average time-to-recovery',
