  /* ── additional-services.html (private client services) ───── */
  as_hero_eyebrow:    'Private client services \u2022 LLC formation \u2022 Business plans \u2022 Contract & immigration review',
  as_hero_title:      'Private-client advisory \u2014 from business opening to contract review.',
  as_hero_lead:       'Seven defined-scope services for founders, families, and individuals: LLC formation, business plans, location analysis, turnkey business opening, contract & lease review, immigration packet preparation, and auto-deal analysis. Every engagement has a clear scope, a defined timeframe, and a delivered document package \u2014 before you commit.',
  as_side_h3:         'Discretion by default',
  as_side_p:          'Every matter is handled one-to-one. No shared workflows, no generic templates. Your documents stay in a single-tenant environment from first message to final deliverable.',
  as_curated_eyebrow: 'Private services',
  as_curated_h2:      'Defined-scope services. Fixed timeframe. Delivered packet.',
  as_curated_intro:   'Each service below lists exactly what you receive, how long it takes, and in what format \u2014 before you commit. No open-ended retainers. No billable-hour uncertainty.',
  as_starts_from:     'Starts from',
  as_card1_h3:        'Contract & Lease Review',
  as_card1_p:         'Independent review of high-stakes documents before you sign. We surface clauses that are outside market norms, fees that deviate from threshold expectations, and commitments that don\u2019t match the verbal agreement.',
  as_card1_li1:       'Side-by-side clause-by-clause review',
  as_card1_li2:       'Risk and negotiation-leverage markup',
  as_card1_li3:       'Plain-language summary memo',
  as_card1_cta1:      'Try free scanner',
  as_card1_cta2:      'Request review',
  as_card2_h3:        'Immigration Packet Preparation',
  as_card2_p:         'Document-organization support for USCIS packets. We build the evidence index, verify the form sequence, and prepare the submission-ready folder. Legal strategy and filing decisions remain with your attorney.',
  as_card2_li1:       'Evidence index and checklist',
  as_card2_li2:       'Form sequence and exhibit tabbing',
  as_card2_li3:       'Submission-readiness walkthrough',
  as_card2_cta1:      'Try free helper',
  as_card2_cta2:      'Request preparation',
  as_card3_h3:        'Auto Deal & Major-Purchase Review',
  as_card3_p:         'Pre-signing analysis of the complete deal sheet. We calculate the true monthly payment, flag dealer fees above common thresholds (doc fee, GAP, extended warranty), and summarize the negotiation points worth raising at the table.',
  as_card3_li1:       'Threshold check on doc fee, GAP, warranty',
  as_card3_li2:       'True monthly payment with APR verification',
  as_card3_li3:       'Negotiation points memo',
  as_card3_cta1:      'Try free calculator',
  as_card3_cta2:      'Request review',
  as_card5_h3:        'LLC Formation & Business Registration',
  as_card5_p:         'Filing-ready packet for a U.S. LLC or corporation; state selected at intake. We coordinate the articles, operating-agreement draft, EIN application, and registered-agent documentation so your filing goes through clean on the first attempt.',
  as_card5_li1:       'Articles of Organization / Incorporation (selected state)',
  as_card5_li2:       'Operating agreement draft + EIN (IRS SS-4)',
  as_card5_li3:       'Registered agent & initial compliance calendar',
  as_card5_scope:     'One U.S. entity + owner documents',
  as_card5_time:      '5\u20137 business days for filing-ready packet',
  as_card5_deliv:     'Filing packet PDF + post-filing checklist',
  as_card5_cta2:      'Request formation packet',
  as_card6_h3:        'Business Plans & Market Research',
  as_card6_p:         'Investor-readable business plan or focused market-research memo. Positioning, unit economics, competitive landscape, and a 3-year financial model with sensitivity ranges \u2014 built to survive a due-diligence read.',
  as_card6_li1:       'Market sizing + competitive landscape',
  as_card6_li2:       'Unit economics + 3-year financial model',
  as_card6_li3:       'Executive summary + 10-page pitch-deck draft',
  as_card6_scope:     'One plan up to 30 pages + appendix',
  as_card6_time:      '10\u201314 business days',
  as_card6_deliv:     'Plan PDF + editable source files',
  as_card6_cta2:      'Request business plan',
  as_card7_h3:        'Turnkey Business Opening',
  as_card7_p:         'Coordinated bundle across formation, licensing, banking, and lease review. One project timeline, one point of contact, one consolidated packet \u2014 structured so you can open on a known date.',
  as_card7_li1:       'LLC/corp formation + licensing packet',
  as_card7_li2:       'Banking & merchant-processing setup guidance',
  as_card7_li3:       'Lease & vendor-contract review',
  as_card7_scope:     'One business opening \u2014 formation through first-day-ready',
  as_card7_time:      '3\u20135 weeks end-to-end',
  as_card7_deliv:     'Consolidated opening packet + project timeline',
  as_card7_cta2:      'Request turnkey plan',
  as_card8_h3:        'Location Analysis (U.S.)',
  as_card8_p:         'Pre-lease diligence on a U.S. address. Demographics, daytime and drive-time traffic, zoning and permit history, and a competitive map \u2014 so the site decision is data-backed before the lease is signed.',
  as_card8_li1:       'Demographics + daytime / drive-time traffic',
  as_card8_li2:       'Zoning, permit history, code notes',
  as_card8_li3:       'Competitive map with drive-time buffers',
  as_card8_scope:     'One U.S. address (+ up to 2 comparables)',
  as_card8_time:      '7\u201310 business days',
  as_card8_deliv:     'Location analysis PDF with comparables',
  as_card8_cta2:      'Request location review',
  as_card4_h3:        'Florida Official Source Locator',
  as_card4_p:         'Routes you to the correct official Florida government portal for tolls, traffic citations, and court records. VitaCoreX does not retrieve records directly \u2014 we point you to the authoritative source.',
  as_card4_li1:       'SunPass, CFX, and county toll portals',
