  as_advisory_h3:     'Corporate advisory remains the primary position',
  as_advisory_p:      'If the matter belongs on the company side\u2014revenue recovery, legal-file control, or a corporate packet\u2014use structured intake instead of this private-client page.',
  as_advisory_cta:    'Open structured intake',
