  rrf_hero_lede:        'Structured AR recovery consulting for operators across the United States — a Florida-originated discipline we retain while serving clients U.S.-wide. Three transparent engagement tiers: Revenue Recovery Diagnostic ($1,500 fixed), Paid Workflow Pilot (from $2,500/mo), and Qualified Net Recovery Pilot ($0 upfront for approved portfolios, success fee only on eligible recovered cash). Not a law firm; not a collection agency. VitaCoreX LLC is a consulting firm; licensed collection is referred out.',
