  rrf_fccpa_text:       'The Florida Consumer Collection Practices Act (FCCPA) regulates licensed debt-collection activity. VitaCoreX consulting stays upstream of that line — we perform diagnostic, workflow, and pre-collection operator-side work, so FCCPA does not apply to our engagement. When licensed collection is warranted, we refer to partner agencies who operate under FCCPA and federal FDCPA.',
