  /* ── rrf_* revenue-recovery-florida ── */
  rrf_hero_eyebrow:     'Pre-collection дисциплина — U.S.-wide AR-консалтинг',
  rrf_hero_title:       'Возврат выручки и AR-консалтинг — U.S.-wide pre-collection дисциплина, documented pilots, retainer-программы.',
  rrf_hero_lede:        'Структурированный AR-recovery консалтинг для операторов по всей территории США — флоридская дисциплина, которую мы сохраняем, обслуживая клиентов U.S.-wide. Три прозрачные ступени: Revenue Recovery Diagnostic ($1,500 фикс.), Paid Workflow Pilot (от $2,500/мес) и Qualified Net Recovery Pilot ($0 upfront для одобренных портфелей, success fee только с eligible возвращённых денег). Не юридическая фирма, не collection-агентство. VitaCoreX LLC — консалтинговая фирма; licensed collection передаётся наружу.',
