  rrf_pilot_intro:      '90-дневный структурированный engagement для U.S.-компаний с квалифицирующимися AR-портфелями. Upfront: $0 для одобренных портфелей. Компенсация — consulting success fee только с eligible возвращённых денег. Исключено: юридические советы, лицензированная collection-активность, consumer-facing third-party collection, представительство в суде, payment custody.',
