  rrf_out_4:            'Credit reporting или furnisher-активность',
  rrf_fccpa_label:      'Florida FCCPA — замечание',
  rrf_fccpa_text:       'Florida Consumer Collection Practices Act (FCCPA) регулирует licensed debt-collection. VitaCoreX-консалтинг остаётся upstream от этой линии — мы выполняем diagnostic, workflow и operator-side pre-collection работу, поэтому FCCPA к нашему engagement не применяется. Когда нужна licensed collection, передаём partner-агентствам, работающим под FCCPA и федеральным FDCPA.',
  rrf_faq_eyebrow:      'FAQ',
  rrf_faq_title:        'Что обычно спрашивают операторы',
  rrf_faq_q1:           'Вы collection-агентство?',
  rrf_faq_a1:           'Нет. VitaCoreX — консалтинговая фирма. Работаем pre-collection. Licensed collection передаётся partner-агентствам.',
  rrf_faq_q2:           'Применяется ли FCCPA к вашей работе?',
  rrf_faq_a2:           'FCCPA регулирует licensed collection-активность. Наш pre-collection консалтинг остаётся upstream от этой границы, так что FCCPA к engagement не применяется. Licensed collection, если нужна, передаётся наружу.',
  rrf_faq_q3:           'Что на самом деле Qualified Net Recovery Pilot?',
  rrf_faq_a3:           '90-дневный структурированный консалтинг-engagement на одобренном AR-портфеле. $0 upfront. Компенсация — consulting success fee только с eligible возвращённых денег за окно пилота. Операторы, не проходящие квалификацию, выбирают между Revenue Recovery Diagnostic ($1,500 фикс.) и Paid Workflow Pilot (от $2,500/мес).',
  rrf_faq_q4:           'Как считается retainer?',
  rrf_faq_a4:           'Еженедельно, не ежемесячно. Tier 1 — $1,350/нед, Tier 2 — $2,150/нед, Tier 3 — $3,250/нед. Scoped и зафиксированы до старта.',
  rrf_faq_q5:           'Какие штаты вы обслуживаете?',
  rrf_faq_a5:           'Мы работаем с операторами по всей территории США. Florida-origin дисциплина сохранена как специализация; multi-state portfolios — стандартный scope; state-specific compliance (например, лицензирование, bond) подтверждаем на intake.',
