  rrf_footer_upl:       'VitaCoreX LLC — консалтинговая фирма. Не юридическая фирма, не collection-агентство. Consulting success fees применяются к recovery-работе и отличны от contingency collection fees. Licensed collection передаётся partner-агентствам, работающим под FCCPA и FDCPA.',

