  /* ── Industries page ────────────────────────────────────────── */
  indp_hero_eyebrow:  'Industrias \u00B7 Entornos operativos donde el modelo encaja',
  indp_hero_title:    'Donde VitaCoreX merece atencion \u2014 y donde no finge encajar.',
  indp_hero_lead:     'Cuatro entornos operativos donde el modelo de recuperacion tiene un lugar natural: healthcare & dental (saldos de paciente con aging mayor a 90, fragmentacion de portales, fugas pre-agencia), fleet & logistics (consumos de fuel-card sin atestacion del conductor, BOLs archivados fuera del invoice, detention sin resolver), contract-heavy services (change orders sin firmas, lien calendars que ya se fueron, cronologias incompletas) y subscription / recurring (retry logic, dunning ladders y flujos card-on-file que nunca se afinaron). Si tu categoria no esta aqui, la respuesta honesta probablemente es otro socio.',
