  abt_founder_role:   'Fundador y Managing Director',
  abt_founder_bio1:   'Steven fundo VitaCoreX LLC en 2025 para cerrar una brecha practica que los operadores describian: trabajo administrativo no lo bastante legal para requerir counsel externo, pero no lo bastante simple para correr limpio in-house \u2014 y que fugaba margen constantemente antes de escalar. La firma se enfoca en tres lineas operativas: diseno de recuperacion de ingresos, control de expediente legal corporativo y admision estructurada de casos.',
  abt_founder_bio2:   'VitaCoreX esta posicionada intencionalmente como asesoria boutique, no-agencia y no-bufete, para que los engagements sigan siendo medibles y los traspasos limpios. Steven trabaja directamente con operadores finance-led y counsel-adjacent que quieren logica de cash control y disciplina de paquetes antes de que crezcan los costos externos. Los puntos de verificacion \u2014 registro Sunbiz, EIN y LinkedIn \u2014 estan disponibles antes de cualquier compromiso de engagement.',
