  prt_upl_p1:         'VitaCoreX no da asesoría legal, no interpreta leyes y no representa clientes en procedimientos judiciales o administrativos. No preparamos pleadings, no presentamos documentos en nombre del cliente y no negociamos obligaciones legales.',
  prt_upl_p2:         'Todo lo que hacemos se clasifica como documentación administrativa, coordinación de workflow y business-support. Si un asunto requiere juicio legal, lo devolvemos explícitamente a su firma.',
  prt_upl_p3:         'Esta posición es resultado directo de la disciplina compliance descrita en los estatutos UPL estatales aplicables (por ejemplo, Chapter 454 Florida Statutes) y las Bar Rules de las jurisdicciones correspondientes.',

