  csfl_situation_eyebrow:'Situación',
  csfl_situation_h2:  'Fuel-card AR atascado entre disputas y facturas olvidadas.',
  csfl_situation_p1:  'Los operadores acumulaban deuda de fuel-card donde la conciliación entre recibos de terminal, reportes de conductores y facturas del proveedor había dejado de ejecutarse regularmente. Parte de la deuda era legítima, parte resultaba de cargos duplicados, parte eran credit notes olvidados. Ningún equipo interno tenía tiempo para la conciliación completa.',
  csfl_situation_p2:  'Los primeros intentos internos produjeron respuesta fragmentada: cada archivo se trataba por separado, sin un marco documental unificado. Al llegar a VitaCoreX, el aging de AR alcanzaba 90+ días sobre el 62% de las posiciones abiertas.',
  csfl_situation_p3:  'Restricción clave: ningún operador quería escalar a collections antes de que la deuda estuviera documentalmente confirmada. Cada paso comunicacional debía estar pre-qualified por documentación.',

  csfl_approach_eyebrow:'Enfoque',
  csfl_approach_h2:   'Conciliación primero \u2014 comunicación sólo después de packet-ready.',
  csfl_approach_p1:   'El trabajo empezaba con la conciliación completa entre fuel-card terminal logs, driver reports y facturas del proveedor. Cada posición se clasificaba en una de cuatro categorías: confirmada, disputable con documentación, requiere credit note, no recuperable.',
  csfl_approach_p2:   'Sólo cuando el archivo alcanzaba estado documented se lanzaba el workflow de comunicación. La primera comunicación siempre iba acompañada de packet con invoice, terminal log, driver slip y position summary. Esto eliminaba 70% de las disputas antes de la primera llamada.',
  csfl_approach_p3:   'Para posiciones disputadas, VitaCoreX coordinaba el intercambio de documentos entre operador y proveedor, pero nunca negociaba montos. Si la posición permanecía disputada tras el intercambio documental, el archivo volvía al operador para la decisión de escalación.',

  csfl_outcomes_eyebrow:'Resultados',
  csfl_outcomes_h2:   'Qué se cerró, qué se dio de baja, qué fue a escalación.',
  csfl_outcomes_th1:  'Categoría',
  csfl_outcomes_th2:  'Volumen',
  csfl_outcomes_th3:  'Resultado',
