  csfl_outcomes_r2_c1:'Credit notes aplicados',
  csfl_outcomes_r2_c2:'$62,400 \u00b7 24 archivos',
  csfl_outcomes_r2_c3:'El proveedor aplicó credit notes olvidados tras conciliación',
  csfl_outcomes_r3_c1:'Dado de baja como no recuperable',
  csfl_outcomes_r3_c2:'$28,900 \u00b7 11 archivos',
