  csfl_redaction_h3:  'Sobre la naturaleza compuesta del caso.',
  csfl_redaction_p:   '\u003Cstrong\u003ECaso compuesto.\u003C/strong\u003E Los detalles se combinan desde tres engagements reales con operadores de flota entre 2024\u20132026. Las cifras, ventanas temporales y pasos de workflow reflejan resultados fácticos. Los nombres de operadores, rutas específicas y características identificables se modificaron para proteger la confidencialidad de los clientes.',

  csfl_cta_eyebrow:   'Si el escenario resuena',
  csfl_cta_h2:        'Abra un structured intake para su contexto de fleet-AR.',
  csfl_cta_p:         'No prometemos resultado idéntico. Cada engagement se evalúa por separado tras la conciliación inicial. Pero si la forma del problema es reconocible \u2014 el marco funciona.',
  csfl_cta_btn:       'Solicitar análisis de fleet-AR',

  /* ── case-study-subscription-saas.html (composite case) ─────── */
  cssa_hero_eyebrow:  'Caso de estudio \u00b7 Engagement compuesto',
  cssa_hero_title:    'SaaS mid-market: 67% de failed-payment recovery en 60 días.',
  cssa_hero_lead:     'Caso compuesto de dos operadores B2B SaaS (ARR anual $8M\u2013$22M) operando en rango post-seed / series-A. El engagement cubrió workflow de failed-payment recovery, documentación dunning y coordinación con el proveedor merchant-processing. Todas las métricas, plazos y pasos de workflow reflejan engagements reales \u2014 la composición protege la identidad de los clientes.',

  cssa_summary_eyebrow:'Executive summary',
  cssa_summary_h2:    'Las cifras que hay que saber antes de seguir leyendo.',
  cssa_summary_k1_l:  'Failed-payment recovery rate',
  cssa_summary_k1_v:  '67%',
  cssa_summary_k2_l:  'Ventana temporal',
  cssa_summary_k2_v:  '60 días',
  cssa_summary_k3_l:  'MRR recuperado',
  cssa_summary_k3_v:  '$184,000',
  cssa_summary_k4_l:  'Cuentas retenidas',
  cssa_summary_k4_v:  '312',

  cssa_situation_eyebrow:'Situación',
  cssa_situation_h2:  'Failed payments que drenaban MRR en silencio.',
  cssa_situation_p1:  'Los operadores funcionaban con baseline failed-payment rate de ~8\u201311% de charges mensuales, típico para B2B SaaS con pagos corporate-card y el ciclo anual de expiraciones de tarjetas. El dunning interno estaba configurado, pero la secuencia retry y el workflow documental llevaban más de 18 meses sin actualizar.',
  cssa_situation_p2:  'El resultado: parte de los failed payments se recuperaba por automated retry, parte se perdía sin comunicación explícita con la cuenta. Los equipos customer-success notaban churn sólo cuando la cuenta ya había cancelado \u2014 demasiado tarde para structured recovery.',
  cssa_situation_p3:  'Ningún operador quería endurecer la comunicación dunning. Se requería un marco donde la cuenta recibiera aviso explícito con suficiente documentación para que el equipo finance del otro lado pudiera procesar el pago sin escalación.',

  cssa_approach_eyebrow:'Enfoque',
  cssa_approach_h2:   'Marco de recovery documentado \u2014 no tácticas dunning agresivas.',
  cssa_approach_p1:   'VitaCoreX realizó una auditoría completa del workflow failed-payment: retry timing, communication templates, escalation thresholds, merchant-processor reporting. La auditoría reveló tres gaps estructurales: ausencia de documentación invoice-level en la primera comunicación, ausencia de aviso explícito pre-expiration y ausencia de reporte consolidado para customer-success.',
  cssa_approach_p2:   'El marco de recovery incluía tres capas: (1) aviso pre-expiration con detalle invoice-level 30 días antes del vencimiento de tarjeta; (2) post-failure packet con invoice, payment history y enlace self-service de actualización; (3) escalation-cue a customer-success en día 21 si la cuenta no respondía.',
  cssa_approach_p3:   'La comunicación se mantenía en registro administrativo \u2014 sin amenazas, sin mención de collections, sin escalación hasta que customer-success tomara decisión. La documentación siempre acompañaba cada paso comunicacional.',

  cssa_outcomes_eyebrow:'Resultados',
  cssa_outcomes_h2:   'Lo recuperado, lo cancelado, lo que fue a structured churn.',
