  as_hero_eyebrow:    'Servicios para clientes privados \u2022 Formacion de LLC \u2022 Planes de negocio \u2022 Revision de contratos e inmigracion',
  as_hero_title:      'Asesoria para clientes privados \u2014 desde apertura de negocio hasta revision de contratos.',
  as_hero_lead:       'Siete servicios de alcance definido para fundadores, familias e individuos: formacion de LLC, planes de negocio, analisis de ubicacion, apertura de negocio llave en mano, revision de contrato y arrendamiento, preparacion de paquete migratorio y analisis de compra de auto. Cada engagement tiene un alcance claro, un plazo definido y un paquete documental entregado \u2014 antes de que te comprometas.',
  as_side_h3:         'Discrecion por defecto',
  as_side_p:          'Cada asunto se maneja uno a uno. Sin flujos compartidos ni plantillas genericas. Tus documentos permanecen en un entorno dedicado desde el primer mensaje hasta la entrega final.',
  as_curated_eyebrow: 'Servicios privados',
