  as_curated_intro:   'Cada servicio abajo indica exactamente que recibes, cuanto tarda y en que formato \u2014 antes de que te comprometas. Sin retainers abiertos. Sin incertidumbre de horas facturables.',
  as_starts_from:     'Desde',
