  /* ── rrf_* revenue-recovery-florida ── */
  rrf_hero_eyebrow:     'Disciplina de pre-cobranza — consultoria de AR a nivel EE. UU.',
  rrf_hero_title:       'Recuperacion de ingresos y consultoria de AR — disciplina pre-cobranza a nivel EE. UU., pilots documentados, programas de retainer.',
  rrf_hero_lede:        'Consultoria estructurada de recuperacion de AR para operadores en todo Estados Unidos — una disciplina originada en Florida que retenemos mientras atendemos clientes a nivel nacional. Tres niveles transparentes: Revenue Recovery Diagnostic ($1,500 fijo), Paid Workflow Pilot (desde $2,500/mes) y Qualified Net Recovery Pilot ($0 upfront para portafolios aprobados, success fee solo sobre efectivo recuperado elegible). No es un bufete; no es agencia de cobranza. VitaCoreX LLC es una firma de consultoria; la cobranza licenciada se deriva fuera.',
  rrf_cta_primary:      'Solicitar el Pilot',
  rrf_cta_secondary:    'Ver programas de retainer',
  rrf_what_eyebrow:     'Que hacemos',
  rrf_what_title:       'Disciplina de AR del lado operador, a nivel EE. UU.',
  rrf_what_intro:       'Consultoria de recuperacion de ingresos para CFOs, controllers y duenos multi-location. Solo pre-cobranza — nos quedamos upstream de la cobranza licenciada.',
  rrf_what_1_title:     'Diagnostico de portfolio AR',
  rrf_what_1_desc:      'Analisis de aging, puntos de fuga, calidad documental y gaps de workflow calificados contra el potencial de recuperacion.',
  rrf_what_2_title:     'Cambio documentado de workflow',
  rrf_what_2_desc:      'Cadencia de outreach estructurada, escalera de escalamiento y tracking de KPI implementados contra tu baseline operacional.',
  rrf_what_3_title:     'Programa de reduccion de DSO',
  rrf_what_3_desc:      'Days Sales Outstanding medido, trackeado y reducido a traves de disciplina pre-cobranza — no por actividad de cobranza.',
  rrf_what_4_title:     'Coordinacion counsel + cobranza',
  rrf_what_4_desc:      'Cuando un archivo necesita cobranza licenciada o counsel, preparamos el paquete y hacemos el handoff. No practicamos ninguna de las dos.',
  rrf_pilot_eyebrow:    'Pilot',
  rrf_pilot_title:      'Qualified Net Recovery Pilot — $0 upfront para portafolios aprobados',
  rrf_pilot_intro:      'Engagement estructurado de 90 dias para empresas de EE. UU. con portafolios AR que califican. Upfront: $0 para portafolios aprobados. La compensacion es una consulting success fee solo sobre efectivo recuperado elegible. Excluye asesoramiento legal, actividad de cobranza licenciada, cobranza consumer-facing de terceros, representacion en tribunal y custodia de pagos.',
  rrf_fee1_range:       '0–90 dias aged',
  rrf_fee1_label:       'del cash recuperado',
  rrf_fee2_range:       '91–180 dias aged',
  rrf_fee2_label:       'del cash recuperado',
  rrf_fee3_range:       '181+ dias aged',
  rrf_fee3_label:       'del cash recuperado',
  rrf_pilot_note:       'Estructurado como consulting success fee de pre-cobranza, no como contingency collection fee. El benchmark del US Chamber para pre-cobranza es 25–33%; los success fees de VitaCoreX estan 25% debajo de los benchmarks comunes.',
  rrf_pilot_link:       'Ver terminos completos del Pilot →',
  rrf_ret_eyebrow:      'Retainers',
  rrf_ret_title:        'Programas de retainer semanal para disciplina continua',
  rrf_ret_intro:        'Para operadores que quieren disciplina de AR de forma permanente. Los retainers son semanales (no mensuales) para ciclos cortos de feedback, faciles de pausar o escalar.',
  rrf_ret_1_name:       'Tier 1 · Single-location',
  rrf_ret_1_desc:       'Mantenimiento de workflow, revision semanal de KPI, intake triage para nuevos casos de AR.',
  rrf_ret_2_name:       'Tier 2 · Multi-location',
  rrf_ret_2_desc:       'Gobierno de AR multi-site, coordinacion de escalamientos, KPI briefs a nivel controller.',
  rrf_ret_3_name:       'Tier 3 · Portfolio / CFO',
  rrf_ret_3_desc:       'Programa de portfolio completo: reporte DSO, deck ejecutivo, manejo de referidos a counsel/cobranza.',
  rrf_ret_link:         'Ver pricing y engagement tiers completos →',
  rrf_how_eyebrow:      'Proceso',
  rrf_how_title:        'Tres fases en 90 dias',
  rrf_step1_title:      'Diagnose',
  rrf_step1_desc:       'Intake review de 7 dias: aging, workflow, calidad de archivo, puntos de fuga. Portfolio fit confirmado.',
  rrf_step2_title:      'Pilot',
  rrf_step2_desc:       'Scope controlado de 90 dias: outreach estructurado, cambio documentado de workflow, tracking de KPI contra baseline.',
  rrf_step3_title:      'Report',
  rrf_step3_desc:       'Deck ejecutivo: cash recuperado, delta de DSO, file-readiness, scope siguiente recomendado (retainer, nuevo pilot o release).',
  rrf_scope_eyebrow:    'Scope y nota FCCPA',
  rrf_scope_title:      'Consultoria, no cobranza — upstream de FCCPA',
  rrf_in_title:         'Incluye',
  rrf_in_1:             'Diagnostico de AR y reporte de baseline',
  rrf_in_2:             'Outreach documentado y workflow de escalamiento',
  rrf_in_3:             'Tracking de KPI (DSO, tasa de recuperacion, velocidad de aging)',
  rrf_in_4:             'Reporte ejecutivo y cadencia de gobierno',
  rrf_in_5:             'Preparacion de paquete counsel o cobranza cuando hay referral',
  rrf_out_title:        'No incluye',
  rrf_out_1:            'Actividad de cobranza licenciada (se deriva)',
  rrf_out_2:            'Asesoramiento legal o representacion (counsel externo)',
  rrf_out_3:            'Cobranza al consumidor final',
  rrf_out_4:            'Reporte de credito o actividad de furnisher',
  rrf_fccpa_label:      'Nota sobre FCCPA en Florida',
  rrf_fccpa_text:       'La Florida Consumer Collection Practices Act (FCCPA) regula la actividad licenciada de cobranza. La consultoria de VitaCoreX se mantiene upstream de esa linea — hacemos trabajo diagnostico, de workflow y pre-cobranza del lado operador, por lo que FCCPA no aplica a nuestro engagement. Cuando se justifica cobranza licenciada, referimos a agencias partner que operan bajo FCCPA y FDCPA federal.',
  rrf_faq_eyebrow:      'FAQ',
  rrf_faq_title:        'Lo que los operadores preguntan primero',
  rrf_faq_q1:           'Son una agencia de cobranza?',
  rrf_faq_a1:           'No. VitaCoreX es firma de consultoria. Trabajamos pre-cobranza. La cobranza licenciada se deriva a agencias partner.',
  rrf_faq_q2:           'Aplica FCCPA a su trabajo?',
  rrf_faq_a2:           'FCCPA regula la actividad licenciada de cobranza. Nuestra consultoria de pre-cobranza se mantiene upstream de esa frontera, por lo que FCCPA no aplica al engagement. Si se necesita cobranza licenciada, se deriva.',
  rrf_faq_q3:           'Que es realmente el Qualified Net Recovery Pilot?',
  rrf_faq_a3:           'Un engagement de consultoria estructurado de 90 dias sobre un portafolio AR aprobado. $0 upfront. La compensacion es una consulting success fee solo sobre efectivo recuperado elegible durante la ventana del pilot. Los operadores que no califican eligen entre el Revenue Recovery Diagnostic ($1,500 fijo) y el Paid Workflow Pilot (desde $2,500/mes).',
  rrf_faq_q4:           'Como se cobran los retainers?',
  rrf_faq_a4:           'Semanal, no mensual. Tier 1 $1,350/sem, Tier 2 $2,150/sem, Tier 3 $3,250/sem. Scoped y fijados antes de empezar.',
  rrf_faq_q5:           'Que estados atienden?',
  rrf_faq_a5:           'Atendemos operadores en todo Estados Unidos. La disciplina originada en Florida se preserva como especialidad; los portfolios multi-estado son scope estandar; el compliance especifico del estado (p. ej., licencia, bond) se confirma en intake.',
  rrf_final_title:      'Solicita el Pilot o cotiza un retainer',
  rrf_final_lede:       'La calificacion toma menos de una semana. El scoping de retainer es una sola sesion. Ambos arrancan con una conversacion estructurada sobre tu portfolio.',
  rrf_final_primary:    'Solicitar el Pilot',
  rrf_final_secondary:  'Solicitar una consulta privada',
  rrf_footer_upl:       'VitaCoreX LLC es una firma de consultoria. No es un bufete ni una agencia de cobranza. Los consulting success fees aplican al trabajo de recovery y son distintos de los contingency collection fees. La cobranza licenciada se deriva a agencias partner que operan bajo FCCPA y FDCPA.',

